<template>
  <label
    :class="[
      ns.b(),
      ns.is('disabled', disabled),
      ns.is('error', error),
      ns.is('focus', focus),
      ns.is('bordered', border),
      ns.is('checked', modelValue === actualValue),
      ns.m(size),
    ]"
  >
    <span
      :class="[
        ns.e('input'),
        ns.is('disabled', disabled),
        ns.is('error', error),
        ns.is('checked', modelValue === actualValue),
      ]"
    >
      <input
        ref="radioRef"
        v-model="modelValue"
        :class="ns.e('original')"
        :value="actualValue"
        :name="name || radioGroup?.name"
        :disabled="disabled"
        :checked="modelValue === actualValue"
        type="radio"
        @focus="focus = true"
        @blur="focus = false"
        @change="handleChange"
        @click.stop
      />
      <span :class="ns.e('inner')">
        <svg
          v-if="modelValue === actualValue"
          :class="ns.e('check')"
          viewBox="0 0 10.5 10.5"
          aria-hidden="true"
        >
          <path
            d="M3.41254 9.37345C3.26626 9.37351 3.12141 9.34471 2.98628 9.28871C2.85114 9.2327 2.72839 9.15059 2.62504 9.04707L0.192101 6.61545L1.12048 5.68751L3.41254 7.97957L9.3796 2.01251L10.308 2.94045L4.20004 9.04707C4.09669 9.15059 3.97393 9.2327 3.8388 9.28871C3.70367 9.34471 3.55882 9.37351 3.41254 9.37345Z"
          />
        </svg>
      </span>
    </span>
    <span
      v-if="
        $slots.default ||
        (label !== undefined && label !== null && label !== '')
      "
      :class="ns.e('label')"
      @keydown.stop
    >
      <slot>
        {{ label }}
      </slot>
    </span>
  </label>
</template>

<script lang="ts" setup>
import { nextTick } from 'vue'
import { useNamespace } from '@element-plus/hooks'
import { CHANGE_EVENT } from '@element-plus/constants'
import { radioEmits, radioProps } from './radio'
import { useRadio } from './use-radio'

defineOptions({
  name: 'ElRadio',
})

const props = defineProps(radioProps)
const emit = defineEmits(radioEmits)

const ns = useNamespace('radio')
const {
  radioRef,
  radioGroup,
  focus,
  size,
  disabled,
  error,
  modelValue,
  actualValue,
} = useRadio(props, emit)

function handleChange() {
  nextTick(() => emit(CHANGE_EVENT, modelValue.value))
}
</script>
